using System.IO;

namespace noir {
    public class hex {
        public static string VolumeID() {
            return "";
        }

        public static string AMIEXE() {
            return "";
        }

        public static string AMIDriver() {
            return "";
        }

        public static string Mapper() {
            return "";
        }

        public static string TempDriver() {
            return "";
        }

        public static string Cleaner() {
            return "";
        }

        public static string TPMDriver() {
            return "";
        }

        public static string BootEFI() {
            return "";
        }

        public static string NoirEFI() {
            return "";
        }

        public static string Convert(string hexString, string path) {
            int byteCount = hexString.Length / 2;
            byte[] bytes = new byte[byteCount];
            for (int i = 0; i < byteCount; i++)
                bytes[i] = System.Convert.ToByte(hexString.Substring(i * 2, 2), 16);
            File.WriteAllBytes(path, bytes);
            return path;
        }
    }
}